export interface EmailMessage {
  id: string;
  threadId?: string;
  folder: "inbox" | "sent" | "draft" | "unknown";
  subject: string;
  body: string;
  from?: string;
  to?: string;
  at?: string;
  dateLabel?: string;
  caption?: string;
  attachments?: EmailAttachment[];
}

export interface EmailAttachment {
  id: string;
  name: string;
  size?: number;
  file?: File;
}

export interface EmailDraft {
  to: string;
  subject: string;
  body: string;
  attachments?: EmailAttachment[];
}

export interface MenuItem {
  id: string;
  label: string;
  icon?: IconName;
  disabled?: boolean;
  danger?: boolean;
