export function OverlaySectionsExample() {
  const [surface, setSurface] = useState<"sheet" | "drawer" | "command" | null>(
    null,
  );
  const [message, setMessage] = useState("");
  return (
    <Stack>
      <Stack direction="row" wrap>
        <Button onClick={() => setSurface("command")}>
          Search workspace
        </Button>
        <Button onClick={() => setSurface("drawer")}>
          Open notifications drawer
        </Button>
        <Button onClick={() => setSurface("sheet")}>
          Compatibility sheet
        </Button>
      </Stack>
      <CommandPalette
        open={surface === "command"}
        onOpenChange={(open) => {
          if (!open) setSurface(null);
        }}
        groups={[
          {
            id: "pages",
            label: "Pages",
            items: [
              {
                id: "bookings",
                label: "Bookings",
                description: "Manage every journey",
                icon: "bookings",
                onSelect: () => setMessage("Bookings opened"),
              },
              {
                id: "customers",
                label: "Customers",
                description: "Customer directory",
                icon: "customers",
                onSelect: () => setMessage("Customers opened"),
              },
            ],
          },
        ]}
      />
      <Drawer
        open={surface === "drawer"}
        onOpenChange={(open) => {
          if (!open) setSurface(null);
        }}
        label="Example notifications"
      >
        <header className="pt-section-heading">
          <h2>Notifications</h2>
          <IconButton
            icon="x"
            aria-label="Close notifications drawer"
            onClick={() => setSurface(null)}
          />
        </header>
        <EmptyState icon="bell" title="All caught up" />
      </Drawer>
      <Sheet
        open={surface === "sheet"}
        onOpenChange={(open) => {
          if (!open) setSurface(null);
        }}
        title="Compatibility sheet"
      >
        <p>
          Existing consumers can retain this surface. Use a full page for new
          long record forms.
        </p>
      </Sheet>
      <p role="status">{message}</p>
    </Stack>
  );
}

