import {Stack, MiniCalendar, EventRow, Agenda, AgendaSummary, EVENT_KINDS, type CalendarEvent, toast} from "@parya/design-system";
import "@parya/design-system/styles.css";

export function CalendarSectionsExample() {
  const [date, setDate] = useState("2026-11-10");
  const events: CalendarEvent[] = [
    {
      id: "e1",
      kind: "departure",
      date: "2026-11-10",
      time: "09:30",
      title: "Mehta family · Bali",
      reference: "BK-1042",
      status: "confirmed",
      statusDomain: "booking",
      owner: { name: "Priya Nair" },
    },
    {
      id: "e2",
      kind: "payment",
      date: "2026-11-09",
      title: "Collect remaining balance",
      amount: 64000,
      status: "due",
    },
    {
      id: "e3",
      kind: "task",
      date: "2026-11-11",
      title: "Check traveler documents",
      status: "open",
    },
  ];
  return (
    <Stack>
      <MiniCalendar
        value={date}
        onValueChange={setDate}
        today="2026-11-10"
        events={events}
      />
      <AgendaSummary events={events} today="2026-11-10" />
      <Agenda
        events={events}
        today="2026-11-10"
        from={date}
        to="2026-11-30"
        onOpen={(event) => toast(event.title)}
      />
      <EventRow event={events[0]} today="2026-11-10" />
      <pre>{JSON.stringify(EVENT_KINDS, null, 2)}</pre>
    </Stack>
  );
}

