export function ChartSectionsExample() {
  const data: ChartDatum[] = [
    { label: "Aug", values: { revenue: 380000, cost: 240000 } },
    { label: "Sep", values: { revenue: 460000, cost: 310000 } },
    { label: "Oct", values: { revenue: 530000, cost: 340000 } },
  ];
  const series = [
    { id: "revenue", label: "Revenue" },
    { id: "cost", label: "Cost" },
  ];
  return (
    <Stack>
      <ChartCard
        title="Revenue and cost"
        description="Monthly operating totals"
        value={<Money value={530000} />}
      >
        <AreaChart data={data} series={series} format="money" />
      </ChartCard>
      <ChartCard title="Booking trend">
        <LineChart data={data} series={[series[0]]} format="money" />
      </ChartCard>
      <ChartCard title="Revenue by month">
        <BarChart data={data} series={series} format="money" />
      </ChartCard>
      <ChartCard title="Revenue share">
        <DonutChart
          items={data.map((row) => ({
            id: row.label,
            label: row.label,
            value: row.values.revenue!,
          }))}
          format="money"
        />
      </ChartCard>
      <ChartCard title="Ranked months">
        <BarList
          items={data.map((row) => ({
            id: row.label,
            label: row.label,
            value: row.values.revenue!,
          }))}
          format="money"
        />
        <Sparkline
          label="Revenue"
          values={[380000, 460000, 530000]}
          format="money"
        />
      </ChartCard>
    </Stack>
  );
}

