import {useState} from "react";
import {Stack, Button, Money, KanbanCard, describeKanbanSignal, BoardViewSwitch, KanbanBoard, RecordPreviewPanel, RecordPreviewSection, PRIORITY_LEVELS, type KanbanColumn, toast, DataTable} from "@parya/design-system";
import "@parya/design-system/styles.css";

export function WorkflowSectionsExample() {
  const [view, setView] = useState<"board" | "list">("board");
  const [preview, setPreview] = useState(false);
  const [items, setItems] = useState([
    { id: "q1", stage: "new", title: "Mehta family · Bali", value: 248000 },
    {
      id: "q2",
      stage: "quoting",
      title: "Kerala family holiday",
      value: 126000,
    },
  ]);
  const columns: KanbanColumn[] = [
    { id: "new", label: "New", quickAdd: true },
    { id: "quoting", label: "Quoting" },
    { id: "won", label: "Won" },
  ];
  return (
    <Stack>
      <BoardViewSwitch value={view} onValueChange={setView} />
      {view === "board" ? (
        <div style={{ height: 480 }}>
          <KanbanBoard
            label="Sales pipeline"
            columns={columns}
            items={items}
            getId={(item) => item.id}
            getColumn={(item) => item.stage}
            getItemLabel={(item) => item.title}
            getValue={(item) => item.value}
            columnSummary="total"
            onSelect={() => setPreview(true)}
            onMove={(move) =>
              setItems(
                items.map((item) =>
                  item.id === move.id ? { ...item, stage: move.to } : item,
                ),
              )
            }
            onQuickAdd={(stage, title) =>
              setItems([
                ...items,
                { id: `q${items.length + 1}`, stage, title, value: 0 },
              ])
            }
            renderCard={(item) => (
              <KanbanCard
                title={item.title}
                code={item.id}
                footer={<Money value={item.value} />}
              />
            )}
          />
        </div>
      ) : (
        <DataTable
          rows={items}
          getRowId={(row) => row.id}
          caption="Sales queries"
          columns={[
            { id: "title", header: "Query", render: (row) => row.title },
            { id: "stage", header: "Stage", render: (row) => row.stage },
          ]}
        />
      )}
      <Button onClick={() => setPreview(true)}>
        Open compatibility preview
      </Button>
      <RecordPreviewPanel
        open={preview}
        onOpenChange={setPreview}
        title="Mehta family · Bali"
        reference="Q-1042"
        onOpenRecord={() => {
          setPreview(false);
          toast("Full record page selected");
        }}
      >
        <RecordPreviewSection title="Journey">
          <p>5 nights · 4 travelers</p>
        </RecordPreviewSection>
      </RecordPreviewPanel>
      <pre>
        {JSON.stringify(
          {
            priorities: PRIORITY_LEVELS,
            overdue: describeKanbanSignal({
              kind: "due",
              date: "2026-11-08",
              today: "2026-11-10",
            }),
          },
          null,
          2,
        )}
      </pre>
    </Stack>
  );
}

