      service: "hotel",
      location: "Munnar",
      balance: 18000,
    },
    {
      id: "V-004",
      name: "Trailmakers Experiences",
      service: "activity",
      location: "Kochi",
      balance: 8500,
    },
    {
      id: "V-005",
      name: "Brunton Boatyard",
      service: "hotel",
      location: "Kochi",
      balance: 0,
