exampleCode:
export function MenuDemo() {
  const reference = "BK-1042";
  return (
    <Menu
      label="Booking actions"
      trigger={<Button trailingIcon="chevron-down">Actions</Button>}
      items={[
        {
          id: "copy",
          label: "Copy reference",
          icon: "copy",
          onSelect: () => {
            void navigator.clipboard.writeText(reference).then(
              () => toast("Reference copied"),
              () =>
                toast(`Copy this reference: ${reference}`, { tone: "info" }),
            );
          },
        },
        {
          id: "download",
          label: "Download sample itinerary",
          icon: "download",
          onSelect: () => {
            const url = URL.createObjectURL(
              new Blob(
                [
                  `${reference}\nMehta family · Bali\n10–15 November 2026\n2 adults, 1 child`,
                ],
                { type: "text/plain;charset=utf-8" },
              ),
            );
            const link = document.createElement("a");
            link.href = url;
            link.download = "BK-1042-itinerary.txt";
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
          },
        },
      ]}
    />
  );
}

