  const [message, set] = useState("PDF or image, up to 5 MB.");
  return (
    <FileDropzone
      label="Upload traveler documents"
      description={message}
      accept=".pdf,image/*"
      maxBytes={5 * 1024 * 1024}
      onFiles={(files) =>
        set(`${files.length} file selected: ${files[0]?.name}`)
      }
      onError={set}
    />
  );
}

