exampleCode:
export function DataDemo() {
  const rows = [
    {
      id: "BK-1042",
      name: "Mehta family · Bali",
      status: "Confirmed",
      amount: 248000,
    },
    {
      id: "BK-1043",
      name: "Sharma couple · Kerala",
      status: "Awaiting payment",
      amount: 86000,
    },
    {
      id: "BK-1044",
      name: "Kapoor group · Dubai",
      status: "Draft",
      amount: 174500,
    },
  ];
  const [selected, set] = useState<string[]>([]);
  return (
    <Stack>
      <DataTable
        rows={rows}
        getRowId={(r) => r.id}
        caption="Recent bookings"
        selected={selected}
        onSelectionChange={set}
        columns={[
          {
            id: "booking",
            header: "Booking",
            sortValue: (r) => r.name,
            render: (r) => <EntityCell name={r.name} description={r.id} />,
          },
          {
            id: "status",
            header: "Status",
            render: (r) => (
              <StatusChip
                tone={
                  r.status === "Confirmed"
                    ? "success"
                    : r.status === "Draft"
                      ? "neutral"
                      : "warning"
                }
              >
                {r.status}
              </StatusChip>
            ),
          },
          {
            id: "amount",
            header: "Total",
            align: "right",
            sortValue: (r) => r.amount,
            render: (r) => <MoneyCell value={r.amount} />,
          },
        ]}
      />
      {selected.length ? (
        <BulkActionBar count={selected.length} onClear={() => set([])}>
          <Button onClick={() => toast("Export requested")}>
            Export
          </Button>
        </BulkActionBar>
      ) : null}
    </Stack>
  );
}

