export interface TableColumn<T> {
  id: string;
  header: string;
  render: (row: T) => ReactNode;
  sortValue?: (row: T) => SortValue;
  align?: "left" | "right";
}

export interface SortState {
  id: string;
  direction: "asc" | "desc";
}

